-- TABELA servprodcusto

DROP TABLE IF EXISTS `servprodcusto`;
CREATE TABLE `servprodcusto` (
  `Controle` int NOT NULL AUTO_INCREMENT,
  `idEmpresa` int NOT NULL,
  `ValorCusto` decimal(10,2) NOT NULL,
  `Data` date NOT NULL,
  `Unidade` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `ServProd` int NOT NULL,
  `ValorVenda` decimal(10,2) NOT NULL,
  `DataAlt` datetime DEFAULT NULL,
  PRIMARY KEY (`Controle`)
) ENGINE=InnoDB AUTO_INCREMENT=250 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

